    GRADES: GRADES,
    CNS_ACTIONS: CNS_ACTIONS,
    TOTAL_MAX: TOTAL_MAX,
    BONUS_CAP: BONUS_CAP,
    PENALTY_CAP: PENALTY_CAP,
    MONTHS: MONTHS,
